import time
import numpy as np

def construct():
    start_time = time.time()
    deadline = start_time + 55  # Safety margin for 90s limit
    
    # Generator polynomial for the [17,9,5] cyclic code (unextended QR code of length 17).
    # g(x) = x^8 + x^5 + x^4 + x^3 + 1
    # Integer representation: bit 8, 5, 4, 3, 0 are set.
    g = (1 << 8) | (1 << 5) | (1 << 4) | (1 << 3) | (1 << 0)
    
    # Precompute the 9 basis vectors for the [17,9,5] code.
    # The i-th basis vector corresponds to the codeword generated by message x^i.
    # c_i(x) = x^i * g(x).
    # Since deg(g)=8 and i is in 0..8, max degree is 16, which fits in 17 bits (indices 0..16).
    basis_17 = []
    for i in range(9):
        vec = g << i
        basis_17.append(vec)
        
    # Extend each basis vector to length 18 by adding an overall parity bit.
    # The [17,9,5] code has odd minimum distance (5).
    # Extension to [18,9,6] requires adding a parity bit to ensure even weight.
    # Parity bit is placed at index 17.
    basis_18 = []
    for vec in basis_17:
        weight = bin(vec).count('1')
        parity = weight & 1
        ext_vec = vec
        if parity:
            ext_vec |= (1 << 17)
        basis_18.append(ext_vec)
        
    # Generate all 512 codewords using efficient numpy operations
    # Build a lookup table for all 512 combinations
    words = []
    for msg in range(512):
        c_val = 0
        m = msg
        for i in range(9):
            if m & 1:
                c_val ^= basis_18[i]
            m >>= 1
        words.append(c_val)
        
        if time.time() > deadline:
            return words
    
    # Verify all pairwise distances are >= 6
    # For 512 words, that's ~130k pairs - do it efficiently
    words_arr = np.array(words, dtype=np.uint32)
    
    # Spot check: verify a subset of pairs to confirm validity
    # Full check of all C(512,2) = 130816 pairs
    min_dist = 18  # Start high
    # Use a faster popcount method. int.bit_count() is available in Python 3.10+
    # Fallback to bin(x).count('1') if not available, but assume modern python.
    try:
        popcount = lambda x: x.bit_count()
    except AttributeError:
        popcount = lambda x: bin(x).count('1')
        
    for i in range(512):
        if time.time() > deadline:
            break
        # Compute distances from word i to all words j > i
        xors = words_arr[i] ^ words_arr[i+1:]
        # Population count
        dists = np.array([popcount(x) for x in xors])
        if len(dists) > 0:
            min_d = np.min(dists)
            if min_d < min_dist:
                min_dist = min_d
            if min_dist < 6:
                # Invalid code - fall back to greedy construction
                return _greedy_construct(start_time, deadline)
    
    return words

def _greedy_construct(start_time, deadline):
    """Fallback: greedy construction of maximum distance code."""
    N = 18
    MIN_DIST = 6
    words = [0]  # Start with zero word
    
    # Precompute all possible 18-bit words? No, too many.
    # Instead, use a smarter approach: start with known good codes and try to add
    
    # Try adding words from the extended QR code one by one
    g = (1 << 8) | (1 << 5) | (1 << 4) | (1 << 3) | (1 << 0)
    basis_18 = []
    for i in range(9):
        vec = g << i
        weight = bin(vec).count('1')
        if weight & 1:
            vec |= (1 << 17)
        basis_18.append(vec)
    
    # Generate all 512 QR code words and try to include as many as possible
    qr_words = []
    for msg in range(512):
        c_val = 0
        m = msg
        for i in range(9):
            if m & 1:
                c_val ^= basis_18[i]
            m >>= 1
        qr_words.append(c_val)
    
    # Sort by weight (heuristic: lighter words first might help)
    qr_words.sort(key=lambda x: bin(x).count('1'))
    
    for w in qr_words:
        if time.time() > deadline:
            break
        # Check if w can be added
        can_add = True
        for existing in words:
            if bin(w ^ existing).count('1') < MIN_DIST:
                can_add = False
                break
        if can_add:
            words.append(w)
    
    # Also try to add some random words to see if we can exceed QR code size
    # But A_2(18,6) = 512, so we shouldn't be able to
    return words
